from fractions import Fraction

seviye = {Fraction(81): 1}
toplam = Fraction(0)
k = 0
while seviye:
    s = sum(b * c for b, c in seviye.items())
    dugum = sum(seviye.values())
    toplam += s
    print("seviye %2d | dugum %3d | toplam %8.3f" % (k, dugum, float(s)))
