def acgozlu(paralar, tutar):
    k, kalan = 0, tutar
    for p in sorted(paralar, reverse=True):
        k += kalan // p
        kalan %= p
    return k if kalan == 0 else None

def en_iyi(paralar, tutar):
    INF = float("inf")
    dp = [0] + [INF] * tutar
    for a in range(1, tutar + 1):
        for p in paralar:
            if p <= a and dp[a - p] + 1 < dp[a]:
                dp[a] = dp[a - p] + 1
    return dp[tutar]

def ilk_karsi_ornek(paralar, ust=200):
    for t in range(1, ust + 1):
        a, o = acgozlu(paralar, t), en_iyi(paralar, t)
        if a is not None and a != o:
            return t, a, o
    return None

for paralar in ([1, 5, 10, 25], [1, 3, 4], [1, 7, 10], [1, 2, 5, 10, 20, 50]):
    s = ilk_karsi_ornek(paralar)
    if s:
        print("%-24s ilk karsi ornek: tutar=%d  acgozlu=%d  en iyi=%d"
              % (str(paralar), s[0], s[1], s[2]))
