def pi_tablo(p):
    m = len(p)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k > 0 and p[k] != p[i]:
            k = pi[k - 1]
        if p[k] == p[i]:
            k += 1
        pi[i] = k
    return pi

def naif(t, p):
    n, m = len(t), len(p)
    c = 0
    bulunan = []
    for s in range(n - m + 1):
        i = 0
        while i < m:
            c += 1
            if t[s + i] != p[i]:
                break
            i += 1
        if i == m:
            bulunan.append(s)
    return c, bulunan

def kmp(t, p):
    pi = pi_tablo(p)
    n, m = len(t), len(p)
    k = c = 0
    bulunan = []
    for i in range(n):
        while k > 0 and p[k] != t[i]:
            c += 1
            k = pi[k - 1]
        c += 1
        if p[k] == t[i]:
            k += 1
        if k == m:
            bulunan.append(i - m + 1)
            k = pi[k - 1]
    return c, bulunan

