# Dogrudan eslemeli onbellek benzetimi: 32 KB, 64 baytlik satir -> 512 kume
SATIR = 64          # bayt
KUME = 512          # 32768 / 64
ELEMAN = 8          # double = 8 bayt
N = 256             # NxN matris

def iska_say(erisimler):
    etiket = [-1] * KUME
    iska = 0
    for adres in erisimler:
        blok = adres // SATIR
        k = blok % KUME
        if etiket[k] != blok:
            etiket[k] = blok
            iska += 1
    return iska

def satir_oncelikli():
    for i in range(N):
        for j in range(N):
            yield (i * N + j) * ELEMAN

def sutun_oncelikli():
    for j in range(N):
        for i in range(N):
            yield (i * N + j) * ELEMAN

def bloklu(bb):
    for i0 in range(0, N, bb):
        for j0 in range(0, N, bb):
            for i in range(i0, i0 + bb):
                for j in range(j0, j0 + bb):
                    yield (i * N + j) * ELEMAN

a = iska_say(satir_oncelikli())
b = iska_say(sutun_oncelikli())
c = iska_say(bloklu(32))
print("erisim sayisi        : %d" % (N * N))
print("satir oncelikli iska : %6d  (kuram N^2/8 = %d)" % (a, N * N // 8))
print("sutun oncelikli iska : %6d  (kuram N^2 = %d)" % (b, N * N))
print("bloklu (32x32) iska  : %6d" % c)
print("sutun/satir orani    : %.1f" % (b / a))
